<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { NotebookPen, Plus, Search } from 'lucide-vue-next'
import Pager from '../components/Pager.vue'
import RecordTimeline from '../components/RecordTimeline.vue'
import { api, isArchived, messageOf, query, recordTypes, ui } from '../api'
import type { Attachment, Page, RecordEntry } from '../types'
const props=defineProps<{revision:number;initialQuery?:string}>();const emit=defineEmits<{record:[project:string];image:[a:Attachment]}>()
const records=ref<RecordEntry[]>([]),project=ref(''),type=ref(''),search=ref(props.initialQuery||''),total=ref(0),offset=ref(0),loading=ref(false),error=ref('');const limit=30
async function load(){loading.value=true;error.value='';try{const page=await api<Page<RecordEntry>>(`/api/records?${query({project_id:project.value,type:type.value,q:search.value,limit,offset:offset.value})}`);records.value=page.items;total.value=page.total}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
onMounted(load);watch(()=>props.revision,load);watch([project,type],()=>{offset.value=0;void load()});watch(()=>props.initialQuery,q=>{search.value=q||'';offset.value=0;void load()});function page(next:number){offset.value=next;void load()}
</script>
<template><div class="page-heading"><div><h1>现场记录</h1><p class="page-description">沿着时间，找回每一次发现和决定。</p></div><button class="button primary" :disabled="isArchived(project)" @click="emit('record',project)"><Plus :size="18"/>新增记录</button></div><form class="filter-bar" @submit.prevent="offset=0;load()"><select v-model="project" aria-label="记录所属项目"><option value="">全部项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><select v-model="type" aria-label="记录类型"><option value="">全部类型</option><option v-for="(name,key) in recordTypes" :key="key" :value="key">{{name}}</option></select><div class="input-with-icon"><Search :size="16"/><input v-model="search" placeholder="搜索记录内容或标签" aria-label="搜索记录"/></div><button type="submit" class="button subtle">查询</button></form><div v-if="error" class="error-banner" role="alert">{{error}}<button class="text-button" @click="load">重试</button></div><section class="surface records-surface"><div class="section-heading"><h2>记录时间线</h2><span class="muted">{{total}} 条记录</span></div><p v-if="loading" class="loading-message">正在读取记录…</p><div v-else-if="!records.length" class="empty-state"><NotebookPen :size="38"/><h2>留住现场的一手信息</h2><p>记录事实、附上图片、标记项目；需要时随时查回。</p><button class="button primary" :disabled="isArchived(project)" @click="emit('record',project)">写下第一条记录</button></div><div v-else class="timeline-wrap"><RecordTimeline :records="records" show-date @image="emit('image',$event)"/></div><Pager :offset="offset" :limit="limit" :total="total" @change="page"/></section></template>
